def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            # Shift character by 4 positions in the alphabet
            shift = ord(char) + 4
            if char.islower():
                if shift > ord('z'):
                    shift -= 26
            elif char.isupper():
                if shift > ord('Z'):
                    shift -= 26
            result.append(chr(shift))
        else:
            result.append(char)  # Non-alphabetical characters remain unchanged
    return ''.join(result)

